package main

import (
	"fmt"
	"os"
	"syscall"
	"unsafe"
)

type winsize struct {
	Row    uint16
	Col    uint16
	Xpixel uint16
	Ypixel uint16
}

func getTerminalSize(fd int) (int, int, error) {
	var ws winsize
	_, _, err := syscall.Syscall(syscall.SYS_IOCTL, uintptr(fd), uintptr(syscall.TIOCGWINSZ), uintptr(unsafe.Pointer(&ws)))
	if err != 0 {
		return 80, 24, err
	}
	return int(ws.Col), int(ws.Row), nil
}

func main() {
	cols, rows, err := getTerminalSize(int(os.Stdout.Fd()))
	fmt.Printf("cols: %d, rows: %d, err: %v\n", cols, rows, err)
}
EOF

