{"command":"cat << 'EOF' > icons.go
package main

import (
	_ "embed"
	"io/fs"
	"os"
	"path/filepath"
	"strings"
)

//go:embed etc/icons
var iconsContent string

type iconRule struct {
	pattern string
	icon    string
}

var (
	typeIcons = make(map[string]string)
	nameRules = make([]iconRule, 0)
)

func init() {
	lines := strings.Split(iconsContent, "\n")
	for _, line := range lines {
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		// strip comment from line
		if idx := strings.Index(line, " #"); idx != -1 {
			line = strings.TrimSpace(line[:idx])
		}
		fields := strings.Fields(line)
		if len(fields) < 2 {
			continue
		}
		key := fields[0]
		val := fields[1]

		if len(key) == 2 && !strings.Contains(key, "*") && !strings.Contains(key, ".") {
			typeIcons[key] = val
		} else {
			nameRules = append(nameRules, iconRule{pattern: key, icon: val})
		}
	}
}

func getIcon(entry fs.DirEntry, path string) string {
	name := entry.Name()
	lowerName := strings.ToLower(name)

	// Check name rules
	for _, rule := range nameRules {
		pat := rule.pattern
		if strings.HasPrefix(pat, "'") && strings.HasSuffix(pat, "'") {
			pat = pat[1 : len(pat)-1]
		}
		if strings.HasPrefix(pat, "*") {
			suffix := pat[1:]
			if strings.HasSuffix(lowerName, strings.ToLower(suffix)) || strings.HasSuffix(name, suffix) {
				return rule.icon
			}
		} else if strings.EqualFold(name, pat) {
			return rule.icon
		}
	}

	// Type fallbacks
	info, err := entry.Info()
	var mode os.FileMode
	if err == nil {
		mode = info.Mode()
	}

	if entry.IsDir() {
		if ic, ok := typeIcons["di"]; ok {
			return ic
		}
		return ""
	}
	if mode&os.ModeSymlink != 0 {
		if ic, ok := typeIcons["ln"]; ok {
			return ic
		}
		return ""
	}
	if mode&0111 != 0 {
		if ic, ok := typeIcons["ex"]; ok {
			return ic
		}
		return ""
	}

	if ic, ok := typeIcons["fi"]; ok {
		return ic
	}
	return ""
}
EOF
"}

