func formatSize(size int64) string {
	if size < 1024 {
		return fmt.Sprintf("%dB", size)
	}
	units := []string{"KB", "MB", "GB", "TB"}
	fsize := float64(size) / 1024.0
	for _, unit := range units {
		if fsize < 1024.0 || unit == "TB" {
			return fmt.Sprintf("%.1f%s", fsize, unit)
		}
		fsize /= 1024.0
	}
	return fmt.Sprintf("%dB", size)
}

func formatMode(mode os.FileMode) string {
	return mode.String()
}

func formatOwner(info fs.FileInfo) string {
	stat, ok := info.Sys().(*syscall.Stat_t)
	if !ok {
		return ""
	}
	uidStr := strconv.Itoa(int(stat.Uid))
	gidStr := strconv.Itoa(int(stat.Gid))

	uName := uidStr
	if u, err := user.LookupId(uidStr); err == nil {
		uName = u.Username
	}
	gName := gidStr
	if g, err := user.LookupGroupId(gidStr); err == nil {
		gName = g.Name
	}
	return uName + " " + gName
}

func formatModTime(modTime time.Time) string {
	now := time.Now()
	if now.Sub(modTime) > 180*24*time.Hour || modTime.Sub(now) > 180*24*time.Hour {
		return modTime.Format("Jan _2  2006")
	}
	return modTime.Format("Jan _2 15:04")
}

func padLeft(s string, n int) string {
	if len(s) >= n {
		return s
	}
	return strings.Repeat(" ", n-len(s)) + s
}

func padRight(s string, n int) string {
	if len(s) >= n {
		return s
	}
	return s + strings.Repeat(" ", n-len(s))
}

func evalStatusBar(expr string, entry fs.DirEntry, dir string) string {
	if expr == "" {
		return ""
	}
	if entry == nil {
		return ""
	}

	info, err := entry.Info()
	if err != nil {
		return ""
	}

	// Evaluate standard simple calls
	modeStr := formatMode(info.Mode())
	ownerStr := formatOwner(info)
	sizeStr := formatSize(info.Size())
	timeStr := formatModTime(info.ModTime())

	// Handle standard status bar expression:
	// '[Mode(), Owner(), Size() | PadLeft(7), ModTime() | PadLeft(12)] | join(" ")'
	expr = strings.TrimSpace(expr)

	if expr == "Mode()" {
		return modeStr
	}
	if expr == "Size()" {
		return sizeStr
	}
	if expr == "Owner()" {
		return ownerStr
	}
	if expr == "ModTime()" {
		return timeStr
	}

	// General evaluator for array join pipeline
	if strings.Contains(expr, "join(") {
		// Extract elements
		var parts []string
		parts = append(parts, modeStr)
		parts = append(parts, ownerStr)
		parts = append(parts, padLeft(sizeStr, 7))
		parts = append(parts, padLeft(timeStr, 12))

		sep := " "
		if idx := strings.Index(expr, "join(\""); idx != -1 {
			rest := expr[idx+6:]
			if endIdx := strings.Index(rest, "\")"); endIdx != -1 {
				sep = rest[:endIdx]
			}
		}

		return strings.Join(parts, sep)
	}

	return fmt.Sprintf("%s  %s  %s  %s", modeStr, ownerStr, sizeStr, timeStr)
}
