type winsize struct {
	Row    uint16
	Col    uint16
	Xpixel uint16
	Ypixel uint16
}

func getTerminalSize(fd int) (int, int) {
	var ws winsize
	_, _, err := syscall.Syscall(syscall.SYS_IOCTL, uintptr(fd), uintptr(syscall.TIOCGWINSZ), uintptr(unsafe.Pointer(&ws)))
	if err != 0 || ws.Col == 0 || ws.Row == 0 {
		return 80, 24
	}
	return int(ws.Col), int(ws.Row)
}

func setRawMode(fd int) (*syscall.Termios, error) {
	var termios syscall.Termios
	_, _, err := syscall.Syscall(syscall.SYS_IOCTL, uintptr(fd), syscall.TCGETS, uintptr(unsafe.Pointer(&termios)))
	if err != 0 {
		return nil, err
	}
	old := termios
	termios.Iflag &^= syscall.IGNBRK | syscall.BRKINT | syscall.PARMRK | syscall.ISTRIP | syscall.INLCR | syscall.IGNCR | syscall.ICRNL | syscall.IXON
	termios.Oflag &^= syscall.OPOST
	termios.Lflag &^= syscall.ECHO | syscall.ECHONL | syscall.ICANON | syscall.ISIG | syscall.IEXTEN
	termios.Cflag &^= syscall.CSIZE | syscall.PARENB
	termios.Cflag |= syscall.CS8
	termios.Cc[syscall.VMIN] = 1
	termios.Cc[syscall.VTIME] = 0

	_, _, err = syscall.Syscall(syscall.SYS_IOCTL, uintptr(fd), syscall.TCSETS, uintptr(unsafe.Pointer(&termios)))
	if err != 0 {
		return nil, err
	}
	return &old, nil
}

func restoreTerminal(fd int, old *syscall.Termios) {
	if old != nil {
		_, _, _ = syscall.Syscall(syscall.SYS_IOCTL, uintptr(fd), syscall.TCSETS, uintptr(unsafe.Pointer(old)))
	}
}

type Model struct {
	currentDir  string
	entries     []fs.DirEntry
	filtered    []fs.DirEntry
	filteredIdx []int
	cursor      int

	showIcons  bool
	dirOnly    bool
	hideHidden bool
	preview    bool
	withBorder bool
	fuzzy      bool
	showHelp   bool

	searchQuery string
	stagedDel   map[string]bool
	statusMsg   string
	mainColor   string
	removeCmd   string
	openWith    map[string]string
	editor      string
	statusBar   string

	errBox string
}

func parseColor(c string) string {
	if c == "" {
		return "99"
	}
	if strings.HasPrefix(c, "#") && len(c) == 7 {
		r, _ := strconv.ParseInt(c[1:3], 16, 64)
		g, _ := strconv.ParseInt(c[3:5], 16, 64)
		b, _ := strconv.ParseInt(c[5:7], 16, 64)
		// Convert to 256-color
		return strconv.Itoa(16 + 36*int(r/51) + 6*int(g/51) + int(b/51))
	}
	return c
}

func parseOpenWith(s string) map[string]string {
	m := make(map[string]string)
	if s == "" {
		return m
	}
	rules := strings.Split(s, ";")
	for _, rule := range rules {
		rule = strings.TrimSpace(rule)
		if rule == "" {
			continue
		}
		idx := strings.Index(rule, ":")
		if idx != -1 {
			ext := strings.TrimPrefix(strings.TrimSpace(rule[:idx]), ".")
			cmd := strings.TrimSpace(rule[idx+1:])
			m[ext] = cmd
		}
	}
	return m
}

func NewModel(path string, icons, dirOnly, hideHidden, preview, withBorder, fuzzy bool) *Model {
	absPath, err := filepath.Abs(path)
	if err != nil {
		absPath = path
	}

	mainColor := parseColor(os.Getenv("WALK_MAIN_COLOR"))

	editor := os.Getenv("WALK_EDITOR")
	if editor == "" {
		editor = os.Getenv("EDITOR")
	}

	removeCmd := os.Getenv("WALK_REMOVE_CMD")

	openWith := parseOpenWith(os.Getenv("WALK_OPEN_WITH"))
	statusBar := os.Getenv("WALK_STATUS_BAR")

	m := &Model{
		currentDir:  absPath,
		showIcons:   icons,
		dirOnly:     dirOnly,
		hideHidden:  hideHidden,
		preview:     preview,
		withBorder: withBorder,
		fuzzy:       fuzzy,
		stagedDel:   make(map[string]bool),
		mainColor:   mainColor,
		removeCmd:   removeCmd,
		openWith:    openWith,
		editor:      editor,
		statusBar:   statusBar,
	}

	m.loadDirectory(absPath)
	return m
}

func (m *Model) loadDirectory(dir string) {
	// Flush staged deletions for previous directory if any
	m.flushDeletions()

	m.errBox = ""
	entries, err := os.ReadDir(dir)
	if err != nil {
		m.errBox = fmt.Sprintf("open %s: %v", dir, strings.TrimPrefix(err.Error(), "open "+dir+": "))
		if pe, ok := err.(*os.PathError); ok {
			m.errBox = fmt.Sprintf("open %s: %v", pe.Path, pe.Err)
		}
		// Fallback to parent directory or current directory
		parent := filepath.Dir(dir)
		if parent != dir {
			m.currentDir = parent
			entries, _ = os.ReadDir(parent)
		} else {
			m.currentDir = "."
			entries, _ = os.ReadDir(".")
		}
	} else {
		m.currentDir = dir
	}

	sort.Slice(entries, func(i, j int) bool {
		return entries[i].Name() < entries[j].Name()
	})

	m.entries = entries
	m.cursor = 0
	m.filterEntries()
}

func fuzzyMatch(pattern, str string) bool {
	pattern = strings.ToLower(pattern)
	str = strings.ToLower(str)
	pIdx := 0
	for sIdx := 0; sIdx < len(str); sIdx++ {
		if pIdx < len(pattern) && pattern[pIdx] == str[sIdx] {
			pIdx++
		}
	}
	return pIdx == len(pattern)
}

func (m *Model) filterEntries() {
	m.filtered = nil
	m.filteredIdx = nil

	for i, entry := range m.entries {
		name := entry.Name()
		if m.hideHidden && strings.HasPrefix(name, ".") {
			continue
		}
		if m.dirOnly && !entry.IsDir() {
			continue
		}
		if m.fuzzy && m.searchQuery != "" {
			if !fuzzyMatch(m.searchQuery, name) {
				continue
			}
		}
		m.filtered = append(m.filtered, entry)
		m.filteredIdx = append(m.filteredIdx, i)
	}

	if m.cursor >= len(m.filtered) {
		m.cursor = len(m.filtered) - 1
	}
	if m.cursor < 0 {
		m.cursor = 0
	}
}

func (m *Model) flushDeletions() {
	if len(m.stagedDel) == 0 {
		return
	}
	for path := range m.stagedDel {
		if m.removeCmd != "" {
			cmd := exec.Command("sh", "-c", m.removeCmd+" \"$1\"", "--", path)
			_ = cmd.Run()
		} else {
			_ = os.RemoveAll(path)
		}
	}
	m.stagedDel = make(map[string]bool)
}

func (m *Model) renderBox(content string, width int) []string {
	lines := strings.Split(content, "\n")
	maxLen := 0
	for _, l := range lines {
		if len(l) > maxLen {
			maxLen = len(l)
		}
	}
	boxWidth := maxLen + 4
	if boxWidth < width {
		boxWidth = width
	}

	top := "╭" + strings.Repeat("─", boxWidth-2) + "╮"
	bot := "╰" + strings.Repeat("─", boxWidth-2) + "╯"

	res := []string{top}
	for _, l := range lines {
		pad := boxWidth - 2 - len(l)
		leftPad := pad / 2
		rightPad := pad - leftPad
		res = append(res, "│ "+strings.Repeat(" ", leftPad)+l+strings.Repeat(" ", rightPad)+" │")
	}
	res = append(res, bot)
	return res
}

func (m *Model) getEntryString(entry fs.DirEntry, path string) string {
	name := entry.Name()
	if entry.IsDir() {
		name += "/"
	}
	if m.showIcons {
		ic := getIcon(entry, path)
		return ic + " " + name
	}
	return name
}

func isBinary(data []byte) bool {
	if len(data) == 0 {
		return false
	}
	if !utf8.Valid(data) {
		return true
	}
	return bytes.IndexByte(data, 0) != -1
}

func (m *Model) getPreviewLines(entry fs.DirEntry, height, width int) []string {
	if entry == nil {
		return nil
	}
	fullPath := filepath.Join(m.currentDir, entry.Name())

	if entry.IsDir() {
		subEntries, err := os.ReadDir(fullPath)
		if err != nil || len(subEntries) == 0 {
			return m.renderBox("No files", width)
		}
		var lines []string
		for _, se := range subEntries {
			sName := se.Name()
			if se.IsDir() {
				sName += "/"
			}
			lines = append(lines, sName)
			if len(lines) >= height {
				break
			}
		}
		return lines
	}

	// File preview
	f, err := os.Open(fullPath)
	if err != nil {
		return m.renderBox("No preview available", width)
	}
	defer f.Close()

	buf := make([]byte, 4096)
	n, _ := io.ReadFull(f, buf)
	buf = buf[:n]

	if isBinary(buf) {
		return m.renderBox("No preview available", width)
	}

	content := string(buf)
	rawLines := strings.Split(content, "\n")
	var res []string
	for i, l := range rawLines {
		if i >= height {
			break
		}
		if len(l) > width {
			l = l[:width]
		}
		res = append(res, l)
	}
	return res
}

func (m *Model) render(cols, rows int, tty *os.File) {
	var b bytes.Buffer

	// Hide cursor
	b.WriteString("\x1b[?25l")

	if m.preview {
		b.WriteString("\x1b[?1049h\x1b[2J\x1b[H")
	} else {
		b.WriteString("\r")
	}

	headerRows := 1
	statusRows := 1
	listHeight := rows - headerRows - statusRows
	if listHeight < 1 {
		listHeight = 1
	}

	// Header line
	headerText := m.currentDir
	if m.showHelp {
		headerText = "help"
	} else if m.fuzzy {
		headerText = "/" + m.searchQuery
	}

	// Header formatting: \x1b[38;5;231;48;5;59m text \x1b[0m
	b.WriteString(fmt.Sprintf("\x1b[38;5;231;48;5;59m%s\x1b[0m\x1b[K\r\n", headerText))

	if m.showHelp {
		helpLines := []string{
			"",
			"    arrows, hjkl  Move cursor",
			"    enter         Enter directory",
			"    backspace     Exit directory",
			"    space         Toggle preview",
			"    esc, q        Exit with cd",
			"    ctrl+c        Exit without cd",
			"    /             Fuzzy search",
			"    d, delete     Delete file or dir",
			"    y             Copy to clipboard",
			"    .             Hide hidden files",
			"    ?             Show help",
		}
		for _, hl := range helpLines {
			b.WriteString(hl + "\x1b[K\r\n")
		}
	} else if m.errBox != "" {
		boxLines := m.renderBox(m.errBox, cols-4)
		for _, bl := range boxLines {
			b.WriteString(bl + "\x1b[K\r\n")
		}
	} else if len(m.filtered) == 0 {
		b.WriteString("No files\x1b[K\r\n")
	} else if m.preview {
		leftWidth := cols / 2
		rightWidth := cols - leftWidth - 1

		var selectedEntry fs.DirEntry
		if m.cursor >= 0 && m.cursor < len(m.filtered) {
			selectedEntry = m.filtered[m.cursor]
		}

		previewLines := m.getPreviewLines(selectedEntry, listHeight, rightWidth)

		numItems := len(m.filtered)
		rowsPerCol := listHeight
		if numItems < listHeight {
			rowsPerCol = numItems
		}

		for r := 0; r < rowsPerCol; r++ {
			// Left side (file item)
			idx := r
			leftStr := ""
			if idx < numItems {
				entry := m.filtered[idx]
				itemStr := m.getEntryString(entry, filepath.Join(m.currentDir, entry.Name()))
				fullPath := filepath.Join(m.currentDir, entry.Name())

				bgCol := "0"
				if idx == m.cursor {
					bgCol = m.mainColor
				}
				if m.stagedDel[fullPath] {
					bgCol = "196"
				}

				if bgCol != "0" {
					leftStr = fmt.Sprintf("\x1b[38;5;231;48;5;%sm%s\x1b[0m", bgCol, itemStr)
				} else {
					leftStr = itemStr
				}
			}

			// Right side (preview line)
			rightStr := ""
			if r < len(previewLines) {
				rightStr = previewLines[r]
			}

			b.WriteString(fmt.Sprintf("%-*s │ %s\x1b[K\r\n", leftWidth, leftStr, rightStr))
		}
	} else {
		// Column view
		numItems := len(m.filtered)
		rowsPerCol := listHeight
		if rowsPerCol > numItems {
			rowsPerCol = numItems
		}
		if rowsPerCol < 1 {
			rowsPerCol = 1
		}

		numCols := (numItems + rowsPerCol - 1) / rowsPerCol

		// Calculate column widths
		colWidths := make([]int, numCols)
		for i, entry := range m.filtered {
			c := i / rowsPerCol
			str := m.getEntryString(entry, filepath.Join(m.currentDir, entry.Name()))
			if len(str) > colWidths[c] {
				colWidths[c] = len(str)
			}
		}

		for r := 0; r < rowsPerCol; r++ {
			var rowBuf bytes.Buffer
			for c := 0; c < numCols; c++ {
				idx := c*rowsPerCol + r
				if idx >= numItems {
					break
				}
				entry := m.filtered[idx]
				itemStr := m.getEntryString(entry, filepath.Join(m.currentDir, entry.Name()))
				fullPath := filepath.Join(m.currentDir, entry.Name())

				bgCol := "0"
				if idx == m.cursor {
					bgCol = m.mainColor
				}
				if m.stagedDel[fullPath] {
					bgCol = "196"
				}

				w := colWidths[c] + 4
				if c == numCols-1 {
					w = colWidths[c]
				}

				if bgCol != "0" {
					rowBuf.WriteString(fmt.Sprintf("\x1b[38;5;231;48;5;%sm%s\x1b[0m", bgCol, itemStr))
					padLen := w - len(itemStr)
					if padLen > 0 {
						rowBuf.WriteString(strings.Repeat(" ", padLen))
					}
				} else {
					rowBuf.WriteString(fmt.Sprintf("%-*s", w, itemStr))
				}
			}
			b.WriteString(rowBuf.String() + "\x1b[K\r\n")
		}
	}

	// Status bar at bottom
	statusText := ""
	if m.statusMsg != "" {
		statusText = m.statusMsg
	} else if m.statusBar != "" && m.cursor >= 0 && m.cursor < len(m.filtered) {
		statusText = evalStatusBar(m.statusBar, m.filtered[m.cursor], m.currentDir)
	}

	if statusText != "" {
		b.WriteString(fmt.Sprintf("\x1b[38;5;231;48;5;59m%s\x1b[0m\x1b[K", statusText))
	} else {
		b.WriteString("\x1b[K")
	}

	_, _ = tty.Write(b.Bytes())
}

func (m *Model) Run() string {
	tty, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
	if err != nil {
		panic(fmt.Sprintf("could not open a new TTY: %v", err))
	}
	defer tty.Close()

	oldState, _ := setRawMode(int(tty.Fd()))
	defer restoreTerminal(int(tty.Fd()), oldState)

	// Bracketed paste
	_, _ = tty.WriteString("\x1b[?2004h")
	defer func() {
		_, _ = tty.WriteString("\x1b[?2004l\x1b[?25h\x1b[?1002l\x1b[?1003l\x1b[?1006l")
		if m.preview {
			_, _ = tty.WriteString("\x1b[?1049l\x1b[?25h")
		}
	}()

	buf := make([]byte, 128)

	for {
		cols, rows := getTerminalSize(int(tty.Fd()))
		m.render(cols, rows, tty)

		n, err := tty.Read(buf)
		if err != nil {
			break
		}

		key := buf[:n]

		// Handle keys
		if bytes.Equal(key, []byte{3}) { // Ctrl+C
			m.flushDeletions()
			os.Exit(2)
		}

		if m.showHelp {
			if key[0] == '?' || key[0] == 'q' || key[0] == 27 {
				m.showHelp = false
			}
			continue
		}

		if m.fuzzy {
			if key[0] == 27 { // Esc
				m.fuzzy = false
				m.searchQuery = ""
				m.filterEntries()
			} else if key[0] == 127 || key[0] == 8 { // Backspace
				if len(m.searchQuery) > 0 {
					m.searchQuery = m.searchQuery[:len(m.searchQuery)-1]
					m.filterEntries()
				} else {
					m.fuzzy = false
					m.filterEntries()
				}
			} else if key[0] == '\r' || key[0] == '\n' {
				m.fuzzy = false
				m.filterEntries()
			} else if len(key) == 1 && key[0] >= 32 && key[0] <= 126 {
				m.searchQuery += string(key)
				m.filterEntries()
			}
			continue
		}

		// Normal mode keys
		if key[0] == 'q' || (len(key) == 1 && key[0] == 27) {
			m.flushDeletions()
			return m.currentDir
		}

		if key[0] == '?' {
			m.showHelp = true
			continue
		}

		if key[0] == '/' {
			m.fuzzy = true
			m.searchQuery = ""
			m.filterEntries()
			continue
		}

		if key[0] == ' ' {
			m.preview = !m.preview
			continue
		}

		if key[0] == '.' {
			m.hideHidden = !m.hideHidden
			m.filterEntries()
			continue
		}

		// Movement
		numItems := len(m.filtered)
		listHeight := rows - 2
		if listHeight < 1 {
			listHeight = 1
		}
		rowsPerCol := listHeight
		if rowsPerCol > numItems {
			rowsPerCol = numItems
		}
		if rowsPerCol < 1 {
			rowsPerCol = 1
		}

		isDown := bytes.Equal(key, []byte{'j'}) || bytes.Equal(key, []byte{27, '[', 'B'})
		isUp := bytes.Equal(key, []byte{'k'}) || bytes.Equal(key, []byte{27, '[', 'A'})
		isRight := bytes.Equal(key, []byte{'l'}) || bytes.Equal(key, []byte{27, '[', 'C'})
		isLeft := bytes.Equal(key, []byte{'h'}) || bytes.Equal(key, []byte{27, '[', 'D'})
		isHome := bytes.Equal(key, []byte{27, '[', 'H'}) || bytes.Equal(key, []byte{27, '[', '1', ';', '2', 'A'})
		isEnd := bytes.Equal(key, []byte{27, '[', 'F'}) || bytes.Equal(key, []byte{27, '[', '1', ';', '2', 'B'})
		isEnter := key[0] == '\r' || key[0] == '\n'
		isBack := key[0] == 127 || key[0] == 8

		if isHome {
			m.cursor = 0
			continue
		}
		if isEnd {
			if numItems > 0 {
				m.cursor = numItems - 1
			}
			continue
		}

		if isDown {
			if numItems > 0 {
				m.cursor = (m.cursor + 1) % numItems
			}
			continue
		}
		if isUp {
			if numItems > 0 {
				m.cursor = (m.cursor - 1 + numItems) % numItems
			}
			continue
		}

		if isRight {
			if m.cursor >= 0 && m.cursor < numItems {
				entry := m.filtered[m.cursor]
				if entry.IsDir() {
					m.loadDirectory(filepath.Join(m.currentDir, entry.Name()))
				} else {
					c := m.cursor / rowsPerCol
					r := m.cursor % rowsPerCol
					nextIdx := (c+1)*rowsPerCol + r
					if nextIdx < numItems {
						m.cursor = nextIdx
					}
				}
			}
			continue
		}

		if isLeft {
			c := m.cursor / rowsPerCol
			if c > 0 {
				r := m.cursor % rowsPerCol
				m.cursor = (c-1)*rowsPerCol + r
			} else {
				m.loadDirectory(filepath.Dir(m.currentDir))
			}
			continue
		}

		if isEnter {
			if m.cursor >= 0 && m.cursor < numItems {
				entry := m.filtered[m.cursor]
				fullPath := filepath.Join(m.currentDir, entry.Name())
				if entry.IsDir() {
					m.loadDirectory(fullPath)
				} else {
					// Open file
					ext := strings.TrimPrefix(filepath.Ext(entry.Name()), ".")
					cmdStr := m.editor
					if openCmd, ok := m.openWith[ext]; ok {
						cmdStr = openCmd
					}
					if cmdStr == "" {
						cmdStr = "less"
					}

					restoreTerminal(int(tty.Fd()), oldState)

					cmd := exec.Command("sh", "-c", cmdStr+" \"$1\"", "--", fullPath)
					cmd.Stdin = os.Stdin
					cmd.Stdout = os.Stdout
					cmd.Stderr = os.Stderr
					_ = cmd.Run()

					_, _ = setRawMode(int(tty.Fd()))
				}
			}
			continue
		}

		if isBack {
			m.loadDirectory(filepath.Dir(m.currentDir))
			continue
		}

		if key[0] == 'd' || bytes.Equal(key, []byte{27, '[', '3', '~'}) {
			if m.cursor >= 0 && m.cursor < numItems {
				entry := m.filtered[m.cursor]
				fullPath := filepath.Join(m.currentDir, entry.Name())
				if m.stagedDel[fullPath] {
					// Already staged -> execute deletion
					if m.removeCmd != "" {
						cmd := exec.Command("sh", "-c", m.removeCmd+" \"$1\"", "--", fullPath)
						_ = cmd.Run()
					} else {
						_ = os.RemoveAll(fullPath)
					}
					delete(m.stagedDel, fullPath)
					m.loadDirectory(m.currentDir)
				} else {
					m.stagedDel[fullPath] = true
				}
			}
			continue
		}

		if key[0] == 'u' {
			m.stagedDel = make(map[string]bool)
			continue
		}

		if key[0] == 'y' {
			if m.cursor >= 0 && m.cursor < numItems {
				entry := m.filtered[m.cursor]
				fullPath := filepath.Join(m.currentDir, entry.Name())
				m.statusMsg = fmt.Sprintf("copied: %s", fullPath)

				// Copy via OSC 52
				// \x1b]52;c;<base64>\x07
				b64 := base64Encode([]byte(fullPath))
				_, _ = tty.WriteString(fmt.Sprintf("\x1b]52;c;%s\x07", b64))
			}
			continue
		}
	}

	return m.currentDir
}

func base64Encode(data []byte) string {
	const table = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
	var buf bytes.Buffer
	for i := 0; i < len(data); i += 3 {
		b := uint32(data[i]) << 16
		if i+1 < len(data) {
			b |= uint32(data[i+1]) << 8
		}
		if i+2 < len(data) {
			b |= uint32(data[i+2])
		}
		buf.WriteByte(table[(b>>18)&0x3F])
		buf.WriteByte(table[(b>>12)&0x3F])
		if i+1 < len(data) {
			buf.WriteByte(table[(b>>6)&0x3F])
		} else {
			buf.WriteByte('=')
		}
		if i+2 < len(data) {
			buf.WriteByte(table[b&0x3F])
		} else {
			buf.WriteByte('=')
		}
	}
	return buf.String()
}
EOF
"}
